procedure receivePacket() //TSecrと同じTSvalを持つ最初の送信パケットを探し、 //時間差を返す receivedRTT = computeRTT(sendList, receivedTSecr, receivedTime)
//あるreceivedTSecrに対する最小値を挿入する //多くの受信パケットが同じreceivedTSecrを含みうることに注意 insertRTT (RTTlist, receivedRTT, receivedTSecr, receivedTime)
filteredRTT = minLastKMeasures(RTTlist, K=4) baseRTT = minLastNSeconds(RTTlist, N=180) qd = filteredRTT - baseRTT
//ackedBytesは、必要に応じて受信ウィンドウを（縮小させずに） //減らすために使用できるバイト数 ackedBytes = ackedBytes + receiveBytes
if retransmittedPacketDetected then RLWND = DecreaseWindow(RLWND) //RTTごとに1回のみ end if if qd < T then RLWND = IncreaseWindow(RLWND, ackedBytes) else RLWND = DecreaseWindow(RLWND) end if end procedure
